async def get_signals_after(session_id: str, after_seq: int, *, limit: int=500) -> list[dict[str, Any]]:
    """Return signal rows for *session_id* with seq > *after_seq*, ordered by seq."""
    require_file_store()
    if not store_exists():
        return []
    async with _open_db(store_path()) as db:
        cur = await db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='session_signals'")
        if not await cur.fetchone():
            return []
        cur = await db.execute('SELECT id, session_id, seq, kind, op_id, ts, payload FROM session_signals WHERE session_id = ? AND seq > ? ORDER BY seq LIMIT ?', (session_id, after_seq, limit))
        rows = await cur.fetchall()
    import json
    result = []
    for r in rows:
        payload = r['payload']
        if isinstance(payload, str):
            try:
                payload = json.loads(payload)
            except (json.JSONDecodeError, TypeError):
                payload = {}
        result.append({'id': r['id'], 'session_id': r['session_id'], 'seq': r['seq'], 'kind': r['kind'], 'op_id': r['op_id'] or '', 'ts': r['ts'], 'payload': payload or {}})
    return result
